(* [comment removed for export] *)
Lemma mb_cap_bound : forall (es0 : list mbe) (insz0 : Z), mb_ok es0 insz0 -> mb_cap es0 <= insz0 + 2^31.
Proof.
  intros es0 insz0 OK0. pose proof (mb_ok_bounds _ _ OK0) as [B1 B2].
  destruct es0 as [|e es1]. { cbn. lia. }
  destruct (mb_es_snoc_inv (e :: es1) ltac:(discriminate)) as (P & xl & sl & EP).
  pose proof (mb_ok_size (e :: es1) insz0 xl sl OK0 ltac:(rewrite EP; apply in_app_iff; right; left; reflexivity)) as SZ.
  rewrite EP, mb_cap_snoc. rewrite EP, mb_capi_snoc in B2. lia.
Qed.

(* [comment removed for export] *)
Lemma snoc_nodup_ne : forall (P : list mbe) (xl sl x' s' : Z), NoDup (map fst (P ++ [(xl, sl)])) -> In (x', s') P -> x' <> xl.
Proof.
  intros P xl sl x' s' ND IN ->. rewrite map_app in ND. cbn [map fst] in ND.
  apply list.NoDup_app in ND. destruct ND as (_ & NI & _).
  apply (NI xl); [| rewrite elem_of_cons; left; reflexivity].
  apply list_elem_of_In. apply in_map_iff. exists (xl, s'). split; [reflexivity| exact IN].
Qed.

