  Lemma prep_noneed : forall (Q : machine_state -> Prop) (m : mem) (out oe : Z) (j0 j24 j96 j120 h32 h112 : list byte)
      (rax gp tp y0 y1 y2 a0 a1 a2 a3 a4 a5 a6 a7 y3 y4 y5 y6 : word) (F : bvmap 5 word) fc,
    AMBraw m b es out insz (mb_outpos es insz) oe ->
