                          (Z_to_bv 64 0) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 res) (Z_to_bv 64 b)
                          (Z_to_bv 64 2147450880) (Z_to_bv 64 ff) (Z_to_bv 64 (mb_cap es)) (Z_to_bv 64 ff) (Z_to_bv 64 (ff + 96)) (Z_to_bv 64 (b + 56))
                          y3 y4 y5 y6)
                      F (Z_to_bv 64 P_A_PREP_TAIL) fc None m (seg_rom bsegs))) ->
