  Lemma prep_link1 : forall (Q : machine_state -> Prop) (m : mem) (P : list mbe) (xl sl out oe mo x g : Z) (nrem : Z)
      (j0 j24 j96 j120 h32 h112 j16 jx : list byte) (gp tp y0 y1 y2 a1 a2 a3 a4 a5 a6 a7 y3 y4 y5 y6 : word) (F : bvmap 5 word) fc,
    es = P ++ [(xl, sl)] -> ((out = b + 8 /\ mo = x) \/ (out = xl /\ mo = xl)) -> 1 <= nrem -> nrem <= g -> g + 31 <= 2^28 ->
    AMBraw m b es out insz (mb_outpos es insz) oe ->
    rw_cells bsegs m spa (prep_locals1 b n ff j0 j24 j96 j120) ->
    rw_cells bsegs m ff (prep_ff1 ff spa fp h32 h112) ->
    rw_cells bsegs m x [CB 16 j16] -> rw_cells bsegs m (x + 16) [C8 (Z_to_bv 64 g); CB (Z.to_nat (mb_block_size g - 24)) jx] ->
    addressable m x (mb_block_size g) -> 0 < x -> x mod 16 = 0 -> aapp x (mb_block_size g) -> x + mb_block_size g <= aceil ->
    (x + mb_block_size g <= b \/ b + 64 <= x) -> (x + mb_block_size g <= ff \/ ff + 128 <= x) ->
    (forall x' s', In (x', s') es -> x + mb_block_size g <= x' \/ x' + mb_block_size s' <= x) ->
    stk bsegs m lo spa -> mem_inv bsegs m -> ACONST m -> stack0 m lo shi ->
    (forall (m2 : mem) (j120' : list byte) (rax a0x a1x a2x a3x a4x a5x a6x a7x : word) (y0' y1' y2' y3' y4' y5' y6' : word),
       munch [(lo, spa + 184); (b + 8, b + 64); (x, x + 16); (xl, xl + 8)]%Z m m2 -> wmono bsegs m m2 -> mem_inv bsegs m2 ->
       rw_cells bsegs m2 spa (prep_locals1 b n ff j0 j24 j96 j120') ->
       rw_cells bsegs m2 ff (prep_ff1 ff spa fp h32 h112) ->
       stk bsegs m2 lo spa -> ACONST m2 ->
       AMBraw m2 b (es ++ [(x, g)]) mo insz (mb_outpos es insz) nrem ->
       evt bsegs Q (MS (mkR rax (Z_to_bv 64 spa) gp tp y0' y1' y2' sp (Z_to_bv 64 spa) a0x a1x a2x a3x a4x a5x a6x a7x
